theme.css:
.outro .tilt{position:absolute;left:96px;top:285px;width:1088px}
.outro .tilt .win{width:1088px}
.outro .tilt .view{height:330px}
.ring{border-color:#A65F00;box-shadow:0 0 0 5px #F4AA2640}
.label{background:#854C00;color:#fff}
.intro.landing .title{font-size:65px}
.intro.landing .card3d img{background:var(--bg)}
/* A real 720 x 1280 composition, not a crop of the desktop cut. */
html,body{width:720px;height:1280px}
.hud{left:48px;right:48px;top:24px;font-size:16px}
.hud .hr em{display:none}
.kicker{font-size:17px;letter-spacing:.1em}
.intro.landing .copy{left:56px;right:56px;top:65px;bottom:auto;width:auto;justify-content:flex-start}
.intro .pre{font-size:17px;margin-bottom:22px}
.intro .title{font-size:64px;max-width:610px}
.intro.landing .tagline{font-size:25px;max-width:600px;margin-top:20px}
.intro .chip{display:none}
.intro.landing .orbit{left:174px;right:auto;top:435px;width:372px;height:805px}
.intro.landing .card3d{width:372px;height:805px;border:5px solid #172536;border-radius:32px}
.intro.landing .card3d .bar{display:none}
.intro.landing .card3d img{width:362px;height:795px;object-fit:cover;background:var(--bg)}
.stats .copy{left:56px;right:56px;top:155px}
.stats .title{font-size:64px;max-width:600px}
.statrow{left:56px;right:56px;top:460px;display:flex;flex-direction:column;gap:20px}
.stat{padding:25px 30px;display:flex;align-items:center;gap:36px;border-radius:24px}
.stat b{font-size:62px;min-width:75px}
.stat span{font-size:25px;margin:0}
.statfoot{left:56px;right:56px;top:1030px;font-size:27px}
.statlink{left:56px;right:56px;top:1140px;font-size:19px}
.chapter .copy{left:56px;top:85px;bottom:auto;width:608px;justify-content:flex-start}
.chapter .title{font-size:58px;line-height:1.04;margin-top:18px}
.chapter .body{font-size:24px;margin-top:18px;line-height:1.4}
.points{margin-top:20px;gap:10px}
.points li{font-size:21px;padding:10px 15px;border-radius:15px}
.chapter .tilt{left:213px;top:570px;width:294px;height:636px}
.chapter .tilt .win{width:294px;border:4px solid #172536;border-radius:26px}
.chapter .tilt .bar{display:none}
.chapter .tilt .view{height:628px}
.chapter .tilt .glow{width:350px;height:530px;left:-40px;top:0}
.chapter .bignum{right:-10px;bottom:-55px;font-size:400px}
.prog{left:56px;bottom:35px}
.demo-heading{position:absolute;left:56px;right:56px;top:77px;font:700 52px/1.07 var(--head);letter-spacing:-.035em;color:var(--fg)}
.demo-sub{position:absolute;left:56px;right:56px;top:197px;font:22px/1.35 var(--body);color:var(--muted)}
.demo .win{left:145px;top:278px;width:430px;border:5px solid #172536;border-radius:33px}
.demo .bar{display:none}
.demo .view{width:420px;height:909px;background:var(--bg)}
.demo .caption{left:44px;bottom:22px;max-width:632px;padding:12px 18px 12px 12px;font-size:21px;line-height:1.25;border:1px solid var(--line);background:var(--card);color:var(--fg)}
.demo .caption b{width:32px;height:32px;font-size:15px;flex:none}
.demo .ring{border-color:#A65F00;box-shadow:0 0 0 5px #F4AA2640}
.demo .label{font-size:17px;max-width:390px;white-space:normal;background:#854C00;color:white}
.arch .copy{left:56px;right:56px;top:100px}
.arch .title{font-size:60px;line-height:1.07;margin-top:20px}
.arch .cam{top:350px;bottom:75px}
.plane,.plane.tall{width:600px;height:780px;top:50%}
.node,.node.dense,.nshadow{width:240px;height:96px;padding:13px 17px;border-radius:18px}
.node small,.node.dense small{font-size:15px}
.node b,.node.dense b{font-size:24px;margin-top:4px}
.node span,.node.dense span{font-size:18px;margin-top:5px}
.elabel{font-size:16px;padding:7px 11px}
.outro .copy{left:56px;right:56px;top:100px}
.outro .title{font-size:64px;line-height:1.05}
.outro .chip.big{font-size:21px;padding:17px;max-width:608px}
.outro .tilt{position:absolute;left:195px;top:415px;width:330px}
.outro .tilt .win{width:330px;border:4px solid #172536;border-radius:27px}
.outro .tilt .bar{display:none}
.outro .tilt .view{height:697px}
.stackrow{left:56px;right:56px;bottom:90px;gap:8px}
.stackrow span{font-size:17px;padding:8px 12px}
.sign{left:56px;right:56px;bottom:28px;font-size:19px;padding-top:17px}
/* Diagram cards need room for the kind, name and explanatory line. */
.node,.node.dense{height:116px}
.node small,.node.dense small{font-size:13px;line-height:1.15;letter-spacing:.06em}
.node b,.node.dense b{font-size:22px;line-height:1.1}
.node span,.node.dense span{font-size:17px;line-height:1.2;margin-top:5px;flex-shrink:0}
